import type { ObstacleBodyHandle, ObstacleBodySpec, ObstaclePhysicsAdapter } from './types';

const ORIGIN: Vec3 = { x: 0, y: 0, z: 0 };
const Y_AXIS: Vec3 = { x: 0, y: 1, z: 0 };

class RecordingPhysics implements ObstaclePhysicsAdapter {
  readonly bodies: ObstacleBodySpec[] = [];
  readonly disposed: string[] = [];

  private readonly rotations = new Map<string, Quat[]>();

  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle {
    this.bodies.push(spec);
    const log: Quat[] = [];
    this.rotations.set(spec.id, log);
    return {
      setNextRotation: (rotation) => { log.push(rotation); },
      dispose: () => { this.disposed.push(spec.id); },
    };
  }

  rotationsOf(id: string): readonly Quat[] {
    return this.rotations.get(id) ?? [];
  }

  bodyOf(id: string): ObstacleBodySpec | undefined {
    return this.bodies.find((body) => body.id === id);
  }
}

function lastRotation(physics: RecordingPhysics, id: string): Quat {
  const rotation = physics.rotationsOf(id).at(-1);
  if (!rotation) throw new Error('no rotation recorded for ' + id);
  return rotation;
}

function expectVec3Close(actual: Vec3, expected: Vec3): void {
